return $input.all().map((item) => {
  const message = item.json;
  if (typeof message.id !== 'string' || !message.id.trim()) throw new Error('Outlook message id is required');
  if (typeof message.receivedDateTime !== 'string' || Number.isNaN(Date.parse(message.receivedDateTime))) throw new Error('Outlook receivedDateTime is invalid');
  const address = message.from?.emailAddress?.address ?? '';
  const name = message.from?.emailAddress?.name ?? '';
  const sender = name && address ? `${name} <${address}>` : address || name;
  return { json: {
    source: 'outlook',
    messageId: message.id,
    threadId: typeof message.conversationId === 'string' && message.conversationId ? message.conversationId : null,
    sender,
    subject: typeof message.subject === 'string' ? message.subject : '',
    body: typeof message.body?.content === 'string' ? message.body.content : '',
    receivedAt: new Date(message.receivedDateTime).toISOString()
  } };
});
